def persistent_load(self, pid):
    assert pid[0] == "storage"
    data_type = pid[1].data_type
    filename = self.data_base_path + "/" + pid[2]
    return LazyStorage(pid[1], filename)

def lazy_rebuild_tensor_v2(storage, offset, size, stride,
                           requires_grad, hooks, metadata=None):
    return LazyTensor(list(size), storage.kind.data_type,
                      f"offset={offset}")

for name, tensor in state.items():
